export function parseCsvLine(line) {
  const fields = [];
  let current = '';
  let i = 0;

  while (i < line.length) {
    if (line[i] === '"') {
      // Quoted field
      i++;
      while (i < line.length) {
        if (line[i] === '"') {
          if (i + 1 < line.length && line[i + 1] === '"') {
            current += '"';
            i += 2;
          } else {
            i++;
            break;
          }
        } else {
          current += line[i];
          i++;
        }
      }
      fields.push(current);
      current = '';
      if (i < line.length && line[i] === ',') {
        i++;
      }
    } else {
      // Unquoted field
      while (i < line.length && line[i] !== ',') {
        current += line[i];
        i++;
      }
      fields.push(current);
      current = '';
      if (i < line.length && line[i] === ',') {
        i++;
      }
    }
  }

  // Handle trailing comma (empty last field)
  if (line.length > 0 && line[line.length - 1] === ',') {
    fields.push('');
  }

  // Handle empty string input
  if (line.length === 0) {
    fields.push('');
  }

  return fields;
}

