export function deepMerge(base, override) {
  const result = { ...base };
  for (const key of Object.keys(override)) {
    if (
      typeof override[key] === 'object' &&
      override[key] !== null &&
      !Array.isArray(override[key]) &&
      typeof result[key] === 'object' &&
      result[key] !== null &&
      !Array.isArray(result[key])
    ) {
      result[key] = deepMerge(result[key], override[key]);
    } else {
      result[key] = override[key];
    }
  }
  return result;
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { deepMerge } from '../src/merge.js';

test('nested', () => {
  assert.deepEqual(deepMerge({ a: { x: 1 } }, { a: { y: 2 } }), { a: { x: 1, y: 2 } });
});

test('does not mutate base', () => {
  const base = { a: { x: 1 } };
  deepMerge(base, { a: { y: 2 } });
  assert.deepEqual(base, { a: { x: 1 } });
});

test('does not mutate override', () => {
  const override = { a: { y: 2 } };
  deepMerge({ a: { x: 1 } }, override);
  assert.deepEqual(override, { a: { y: 2 } });
});

test('arrays from override replace base value', () => {
  assert.deepEqual(deepMerge({ a: [1, 2] }, { a: [3] }), { a: [3] });
});

test('primitives from override replace base value', () => {
  assert.deepEqual(deepMerge({ a: { x: 1 } }, { a: 2 }), { a: 2 });
  assert.deepEqual(deepMerge({ a: 2 }, { a: { x: 1 } }), { a: { x: 1 } });
});

test('deeply nested plain objects', () => {
  assert.deepEqual(
    deepMerge({ a: { b: { c: 1 } } }, { a: { b: { d: 2 } } }),
    { a: { b: { c: 1, d: 2 } } }
  );
});

