const ROMAN_MAP = [
  [1000, 'M'], [900, 'CM'], [500, 'D'], [400, 'CD'],
  [100, 'C'], [90, 'XC'], [50, 'L'], [40, 'XL'],
  [10, 'X'], [9, 'IX'], [5, 'V'], [4, 'IV'], [1, 'I']
];

const ROMAN_VALUES = new Map([
  ['M', 1000], ['CM', 900], ['D', 500], ['CD', 400],
  ['C', 100], ['XC', 90], ['L', 50], ['XL', 40],
  ['X', 10], ['IX', 9], ['V', 5], ['IV', 4], ['I', 1]
]);

const SINGLE_VALUES = new Map([
  ['M', 1000], ['D', 500], ['C', 100], ['L', 50],
  ['X', 10], ['V', 5], ['I', 1]
]);

export function toRoman(n) {
  if (!Number.isInteger(n) || n < 1 || n > 3999) {
    throw new RangeError('Value must be an integer between 1 and 3999');
  }

  let result = '';
  for (const [value, symbol] of ROMAN_MAP) {
    while (n >= value) {
      result += symbol;
      n -= value;
    }
  }
  return result;
}

export function fromRoman(s) {
  if (typeof s !== 'string' || s.length === 0) {
    throw new Error('Invalid Roman numeral');
  }

  let result = 0;
  let i = 0;

  while (i < s.length) {
    const twoChar = s[i] + (s[i + 1] || '');
    if (ROMAN_VALUES.has(twoChar) && twoChar.length === 2) {
      result += ROMAN_VALUES.get(twoChar);
      i += 2;
    } else if (SINGLE_VALUES.has(s[i])) {
      result += SINGLE_VALUES.get(s[i]);
      i += 1;
    } else {
      throw new Error('Invalid Roman numeral');
    }
  }

  // Validate by converting back
  if (toRoman(result) !== s) {
    throw new Error('Invalid Roman numeral');
  }

  return result;
}

