// Test some known values
const tests = [
  [1, 'I'],
  [4, 'IV'],
  [9, 'IX'],
  [49, 'XLIX'],
  [99, 'XCIX'],
  [499, 'CDXCIX'],
  [999, 'CMXCIX'],
  [3999, 'MMMCMXCIX'],
];

for (const [n, expected] of tests) {
  const roman = toRoman(n);
  const back = fromRoman(roman);
  console.log(`${n} -> ${roman} -> ${back} ${roman === expected && back === n ? 'OK' : 'FAIL'}`);
}

// Error cases
const errorCases = [
  ['toRoman(0)', () => toRoman(0)],
  ['toRoman(4000)', () => toRoman(4000)],
  ['toRoman(-1)', () => toRoman(-1)],
  ['toRoman(3.14)', () => toRoman(3.14)],
  ['fromRoman("")', () => fromRoman('')],
  ['fromRoman("IIII")', () => fromRoman('IIII')],
  ['fromRoman("IC")', () => fromRoman('IC')],
  ['fromRoman("ABC")', () => fromRoman('ABC')],
  ['fromRoman("VX")', () => fromRoman('VX')],
];

for (const [label, fn] of errorCases) {
  try {
    fn();
    console.log(`${label}: FAIL (no error thrown)`);
  } catch (e) {
    console.log(`${label}: OK (${e.constructor.name}: ${e.message})`);
  }
}

