import os, re, json

def count_call_sites(src_dir):
    # First pass: collect all exported function names from src/
    defined_functions = set()
    for root, dirs, files in os.walk(src_dir):
        for fname in files:
            if fname.endswith('.js'):
                path = os.path.join(root, fname)
                with open(path) as f:
                    content = f.read()
                # find export function declarations
                for m in re.finditer(r'export\s+function\s+(\w+)', content):
                    defined_functions.add(m.group(1))

    print("Defined functions:", sorted(defined_functions))

    # Second pass: count real call sites (not in comments)
    call_counts = {fn: 0 for fn in defined_functions}
    call_locations = {fn: [] for fn in defined_functions}

    for root, dirs, files in os.walk(src_dir):
        for fname in files:
            if fname.endswith('.js'):
                path = os.path.join(root, fname)
                with open(path) as f:
                    lines = f.readlines()

                for i, line in enumerate(lines, 1):
                    # skip comment-only lines (simple heuristic)
                    stripped = line.strip()
                    if stripped.startswith('//') or stripped.startswith('/*') or stripped.startswith('*'):
                        continue

                    for fn in defined_functions:
                        # match fn( but not in strings or as method names like .fn(
                        # simple regex: word boundary before fn, ( after
                        # but avoid matching inside import/export declarations
                        if re.search(r'\b' + re.escape(fn) + r'\s*\(', line):
                            # Make sure it's not just an import/export mention
                            if 'import' not in line and 'export' not in line:
                                call_counts[fn] += 1
                                call_locations[fn].append((path, i, stripped))
                            else:
                                # More careful: if it looks like a real call on the line, count it
                                if re.search(r'\b' + re.escape(fn) + r'\s*\([^)]*\)', line):
                                    # but exclude import { fn } from ...
                                    if not line.strip().startswith('import') and not line.strip().startswith('export'):
                                        call_counts[fn] += 1
                                        call_locations[fn].append((path, i, stripped))

    return call_counts, call_locations

counts, locs = count_call_sites('src')
for fn, count in sorted(counts.items(), key=lambda x: -x[1]):
    print(f"{fn}: {count}")
    for l in locs[fn]:
        print(f"  {l[0]}:{l[1]} {l[2]}")

