import os
import re

files_to_update = []

# Find all files mentioning toSlug
for root, dirs, files in os.walk('src'):
    for f in files:
        if f.endswith('.js'):
            path = os.path.join(root, f)
            with open(path) as fh:
                content = fh.read()
            if 'toSlug' in content:
                files_to_update.append(path)

for root, dirs, files in os.walk('test'):
    for f in files:
        if f.endswith('.js'):
            path = os.path.join(root, f)
            with open(path) as fh:
                content = fh.read()
            if 'toSlug' in content:
                files_to_update.append(path)

print("Files to update:", files_to_update)

for path in files_to_update:
    with open(path) as fh:
        content = fh.read()

    # Replace toSlug with centralHelper, but NOT when it's part of toSlugPath
    # Use word boundary regex
    new_content = re.sub(r'\btoSlug\b', 'centralHelper', content)

    if new_content != content:
        with open(path, 'w') as fh:
            fh.write(new_content)
        print(f"Updated {path}")
    else:
        print(f"No changes in {path}")

