import re, os

files_to_check = []
for root, dirs, files in os.walk('.'):
    if 'node_modules' in root:
        continue
    for f in files:
        if f.endswith('.js'):
            files_to_check.append(os.path.join(root, f))

pattern = re.compile(r'\btoSlug\b')

changed = []
for path in files_to_check:
    with open(path, 'r') as fh:
        content = fh.read()
    new_content = pattern.sub('centralHelper', content)
    if new_content != content:
        with open(path, 'w') as fh:
            fh.write(new_content)
        changed.append(path)

print('Changed files:')
for p in changed:
    print(p)

