import json
import os
import glob

files = sorted(glob.glob('configs/**/*.json', recursive=True))

for path in files:
    with open(path, 'r') as f:
        content = f.read()
    data = json.loads(content, object_pairs_hook=dict)

    if data.get('version') == 2:
        continue

    new_data = {}
    has_retry = False

    for key, value in data.items():
        if key == 'version':
            new_data['version'] = 2
        elif key == 'timeoutMs':
            new_data['timeout_s'] = value / 1000.0
        elif key == 'retry':
            new_data['retry'] = {
                'attempts': value['count'],
                'backoff_s': value['backoffMs'] / 1000.0
            }
            has_retry = True
        elif key == 'owners':
            if isinstance(value, str):
                emails = [email.strip().lower() for email in value.split(',')]
                emails = [email for email in emails if email]
                new_data['owners'] = emails
            else:
                new_data['owners'] = value
        else:
            new_data[key] = value

    if not has_retry:
        # Insert retry after timeout_s if present, else at end
        items = list(new_data.items())
        new_items = []
        inserted = False
        for k, v in items:
            new_items.append((k, v))
            if k == 'timeout_s' and not inserted:
                new_items.append(('retry', {'attempts': 0, 'backoff_s': 0}))
                inserted = True
        if not inserted:
            new_items.append(('retry', {'attempts': 0, 'backoff_s': 0}))
        new_data = dict(new_items)

    new_content = json.dumps(new_data, indent=2) + '\n'
    with open(path, 'w') as f:
        f.write(new_content)
    print(f"MIGRATED: {path}")

