import json
import glob

files = sorted(glob.glob('configs/**/*.json', recursive=True))

for path in files:
    with open(path, 'r') as f:
        content = f.read()
    data = json.loads(content, object_pairs_hook=list)

    # Check if already v2
    version = next((v for k, v in data if k == 'version'), None)
    if version == 2:
        print(f"SKIP (already v2): {path}")
        continue

    if version != 1:
        print(f"SKIP (unknown version {version}): {path}")
        continue

    new_data = []
    has_retry = False

    for key, value in data:
        if key == 'version':
            new_data.append(('version', 2))
        elif key == 'timeoutMs':
            new_data.append(('timeout_s', value / 1000.0))
        elif key == 'retry':
            new_data.append(('retry', {
                'attempts': value['count'],
                'backoff_s': value['backoffMs'] / 1000.0
            }))
            has_retry = True
        elif key == 'owners':
            if isinstance(value, str):
                emails = [email.strip().lower() for email in value.split(',')]
                emails = [email for email in emails if email]
                new_data.append(('owners', emails))
            else:
                new_data.append(('owners', value))
        else:
            new_data.append((key, value))

    if not has_retry:
        # Insert retry after timeout_s
        idx = next((i for i, (k, v) in enumerate(new_data) if k == 'timeout_s'), -1)
        if idx >= 0:
            new_data.insert(idx + 1, ('retry', {'attempts': 0, 'backoff_s': 0}))
        else:
            new_data.append(('retry', {'attempts': 0, 'backoff_s': 0}))

    result = dict(new_data)
    new_content = json.dumps(result, indent=2) + '\n'
    with open(path, 'w') as f:
        f.write(new_content)
    print(f"MIGRATED: {path}")

